const body = $json.body || {};
const jiraCredentials = body.jira_credentials || {};
const normalizeSubdomain = (value) => String(value || '')
  .trim()
  .replace(/^https?:\/\//i, '')
  .replace(/\/.*$/, '');
const subdomainRaw = normalizeSubdomain(
  jiraCredentials.subdomain || body.jira_subdomain || body.jiraSubdomain || body.jira_base_url || body.jiraBaseUrl
);
const now = new Date();
const futureDate = new Date(now);
futureDate.setDate(futureDate.getDate() + 14);
const jiraEmail = jiraCredentials.email || body.jira_email || body.jiraEmail || '';
const jiraApiToken = jiraCredentials.api_token || body.jira_api_token || body.jiraApiToken || '';
const jiraAuthBase64 = body.jira_auth_base64 || body.jiraAuthBase64 || (
  jiraEmail && jiraApiToken ? Buffer.from(`${jiraEmail}:${jiraApiToken}`).toString('base64') : ''
);

return [
  {
    json: {
      user_id: String(body.user_id || body.userId || '').trim(),
      requested_at: body.timestamp || new Date().toISOString(),
      google_access_token: body.google_access_token || '',
      jira_subdomain: subdomainRaw,
      jira_email: jiraEmail,
      jira_api_token: jiraApiToken,
      jira_auth_base64: jiraAuthBase64,
      calendar_time_min: now.toISOString(),
      calendar_time_max: futureDate.toISOString(),
      gmail_query: 'is:unread newer_than:7d',
      gmail_max_results: 5,
      jira_jql: 'statusCategory != Done ORDER BY updated DESC',
      jira_max_results: 25
    }
  }
];

const listPayload = $node['Get Unread Email'].json || {};
const decodeBase64Url = (value) => {
  if (!value) return '';
  try {
    const normalized = String(value).replace(/-/g, '+').replace(/_/g, '/');
    const padded = normalized + '='.repeat((4 - (normalized.length % 4)) % 4);
    return Buffer.from(padded, 'base64').toString('utf8');
  } catch {
    return '';
  }
};

const stripHtml = (value) => String(value || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ')
  .trim();

const collectParts = (node, bucket = []) => {
  if (!node || typeof node !== 'object') return bucket;
  bucket.push(node);
  if (Array.isArray(node.parts)) {
    for (const part of node.parts) {
      collectParts(part, bucket);
    }
  }
  return bucket;
};

const extractBody = (payload) => {
  const nodes = collectParts(payload, []);
  const plainPart = nodes.find((part) => part?.mimeType === 'text/plain' && part?.body?.data);
  if (plainPart?.body?.data) {
    return decodeBase64Url(plainPart.body.data).replace(/\s+/g, ' ').trim();
  }
  const htmlPart = nodes.find((part) => part?.mimeType === 'text/html' && part?.body?.data);
  if (htmlPart?.body?.data) {
    return stripHtml(decodeBase64Url(htmlPart.body.data));
  }
  const fallbackPart = nodes.find((part) => part?.body?.data);
  if (fallbackPart?.body?.data) {
    return stripHtml(decodeBase64Url(fallbackPart.body.data));
  }
  return '';
};

const inputItems = $input.all();
const detailedEmails = [];
const fetchErrors = [];

for (const item of inputItems) {
  const detail = item.json || {};
  if (!detail.payload) {
    fetchErrors.push({
      id: detail.id || detail.messageId || 'unknown',
      error: detail.message || detail.error || 'Failed to fetch email detail',
    });
    continue;
  }

  const headers = Array.isArray(detail.payload.headers) ? detail.payload.headers : [];
  const getHeader = (name) => headers.find((header) => String(header.name || '').toLowerCase() === name.toLowerCase())?.value || '';
  const bodyText = extractBody(detail.payload);
  const normalizedBody = (bodyText || detail.snippet || '').slice(0, 1200);

  detailedEmails.push({
    id: detail.id || '',
    threadId: detail.threadId || '',
    from: getHeader('From'),
    subject: getHeader('Subject'),
    date: getHeader('Date'),
    snippet: detail.snippet || '',
    body: normalizedBody,
    labelIds: Array.isArray(detail.labelIds) ? detail.labelIds : [],
  });
}

return [{
  json: {
    emails: detailedEmails,
    source_metrics: {
      total_unread: listPayload.resultSizeEstimate || detailedEmails.length,
      fetched_email_count: detailedEmails.length,
      fetched_message_ids: (Array.isArray(listPayload.messages) ? listPayload.messages : []).map((message) => message.id),
      failed_message_ids: fetchErrors.map((item) => item.id),
    },
    fetch_error: fetchErrors.length ? `Gagal mengambil detail ${fetchErrors.length} email unread` : null,
    fetch_error_details: fetchErrors.slice(0, 5),
  }
}];

const listPayload = $json || {};
const messages = Array.isArray(listPayload.messages) ? listPayload.messages : [];

return [{
  json: {
    emails: [],
    source_metrics: {
      total_unread: listPayload.resultSizeEstimate || 0,
      fetched_email_count: 0,
      fetched_message_ids: messages.map((message) => message.id),
      failed_message_ids: [],
    },
    fetch_error: null,
    fetch_error_details: [],
  }
}];

const raw = String($json.output || $json.text || '').trim();
const match = raw.match(/\{[\s\S]*\}/);
let parsed = {};

if (match) {
  try {
    parsed = JSON.parse(match[0]);
  } catch {
    parsed = {};
  }
}

const sourcePayload = $('Get Upcoming Calendar').item.json || {};
const sourceEvents = Array.isArray(sourcePayload.items) ? sourcePayload.items.slice(0, 3) : [];
const safeSourceMetrics = parsed.source_metrics && typeof parsed.source_metrics === 'object' ? parsed.source_metrics : {};
const sanitizeText = (value, fallback = '') => {
  const normalized = String(value || '').trim();
  return normalized || fallback;
};
const normalizeAgendaIntent = (intent) => {
  const normalized = sanitizeText(intent);
  if (normalized === 'prepare_meeting') return 'prepare_rundown';
  return normalized || 'prepare_rundown';
};
const normalizeAgendaLabel = (label, intent) => {
  const normalized = sanitizeText(label);
  if (!normalized || normalized.toLowerCase() === 'buat agenda') {
    if (intent === 'prepare_rundown') return 'Susun Rundown';
    if (intent === 'prepare_talking_points') return 'Susun Talking Points';
  }
  return normalized || 'Susun Rundown';
};
const buildEventDetails = (event) => {
  if (!event || typeof event !== 'object') return 'Detail agenda belum tersedia.';

  const startLabel = event?.start?.dateTime || event?.start?.date || '-';
  const endLabel = event?.end?.dateTime || event?.end?.date || '-';
  const attendeeText = Array.isArray(event.attendees) && event.attendees.length
    ? `\nPeserta: ${event.attendees.map((attendee) => attendee.email || attendee.displayName).filter(Boolean).join(', ')}`
    : '';

  return `Event: ${event.summary || 'Tanpa judul'}\nWaktu: ${startLabel} - ${endLabel}${event.location ? `\nLokasi: ${event.location}` : ''}${attendeeText}${event.description ? `\nDeskripsi: ${event.description}` : ''}${event.hangoutLink ? `\nGoogle Meet: ${event.hangoutLink}` : ''}`;
};
const buildEventContext = (event, focus = 'event_preparation') => {
  const eventId = sanitizeText(event?.id);
  return {
    briefing_domain: 'calendar',
    focus,
    event_ids: eventId ? [eventId] : [],
    thread_id: eventId,
    event_id: eventId,
    event_summary: sanitizeText(event?.summary, 'Tanpa judul'),
    event_start: sanitizeText(event?.start?.dateTime || event?.start?.date),
    event_end: sanitizeText(event?.end?.dateTime || event?.end?.date),
    event_location: sanitizeText(event?.location),
    event_description: sanitizeText(event?.description),
    event_hangout_link: sanitizeText(event?.hangoutLink),
    event_attendees: Array.isArray(event?.attendees)
      ? event.attendees.map((attendee) => attendee.email || attendee.displayName).filter(Boolean)
      : [],
  };
};
const buildPromptByIntent = (intent, event, fallbackLabel = 'agenda ini') => {
  const details = buildEventDetails(event);
  switch (intent) {
    case 'prepare_rundown':
      return `Buatkan rundown meeting yang ringkas, urutan bahasan, estimasi waktu, dan output yang perlu dicapai untuk ${fallbackLabel} berikut:\n\n${details}`;
    case 'prepare_talking_points':
      return `Buatkan talking points utama, pertanyaan penting, dan outcome yang perlu dicapai untuk ${fallbackLabel} berikut:\n\n${details}`;
    case 'follow_up_event':
      return `Buatkan draft follow-up dan daftar next step untuk ${fallbackLabel} berikut:\n\n${details}`;
    case 'review_schedule_conflict':
      return `Cek apakah ada bentrok jadwal, dependensi waktu, atau komitmen lain yang perlu diwaspadai untuk ${fallbackLabel} berikut. Jika ada risiko, jelaskan mitigasinya.\n\n${details}`;
    case 'enrich_event_notes':
      return `Tolong bantu lengkapi catatan persiapan, kebutuhan, dan hal yang perlu dicek untuk ${fallbackLabel} berikut:\n\n${details}`;
    default:
      return `Analisis agenda berikut dan sarankan tindak lanjut paling relevan.\n\n${details}`;
  }
};
const buildFallbackActions = (event) => {
  return [
    {
      label: 'Susun Rundown',
      intent: 'prepare_rundown',
      target: 'supervisor',
      prompt: buildPromptByIntent('prepare_rundown', event),
      context: buildEventContext(event, 'meeting_rundown'),
    },
    {
      label: 'Susun Talking Points',
      intent: 'prepare_talking_points',
      target: 'supervisor',
      prompt: buildPromptByIntent('prepare_talking_points', event),
      context: buildEventContext(event, 'talking_points'),
    },
    {
      label: event?.hangoutLink ? 'Buat Follow-up' : 'Lengkapi Catatan',
      intent: event?.hangoutLink ? 'follow_up_event' : 'enrich_event_notes',
      target: 'supervisor',
      prompt: buildPromptByIntent(event?.hangoutLink ? 'follow_up_event' : 'enrich_event_notes', event),
      context: buildEventContext(event, event?.hangoutLink ? 'follow_up' : 'event_notes'),
    },
  ];
};
const eventLookup = new Map(
  sourceEvents
    .map((event) => [sanitizeText(event?.id), event])
    .filter(([id]) => id),
);
const normalizeAction = (action, fallbackAction, sourceEvent) => {
  const fallbackContext = fallbackAction?.context && typeof fallbackAction.context === 'object'
    ? fallbackAction.context
    : buildEventContext(sourceEvent);
  const intent = normalizeAgendaIntent(action?.intent || fallbackAction?.intent);
  const label = normalizeAgendaLabel(action?.label || fallbackAction?.label, intent);
  const focus = sanitizeText(action?.context?.focus, fallbackContext.focus || 'event_preparation');
  const context = {
    ...fallbackContext,
    ...(action?.context && typeof action.context === 'object' ? action.context : {}),
    ...buildEventContext(sourceEvent, focus),
  };
  const generatedPrompt = buildPromptByIntent(intent, sourceEvent, label.toLowerCase());
  const providedPrompt = sanitizeText(action?.prompt);

  return {
    label,
    intent,
    target: 'supervisor',
    prompt: providedPrompt
      ? `${providedPrompt}\n\nKonteks agenda lengkap:\n${buildEventDetails(sourceEvent)}`
      : generatedPrompt,
    context,
  };
};
const normalizedAgendaActions = (Array.isArray(parsed.agenda_actions) ? parsed.agenda_actions.slice(0, 3) : [])
  .map((entry, index) => {
    const candidateId = sanitizeText(entry?.id || entry?.threadId);
    const matchedEvent = candidateId ? eventLookup.get(candidateId) : null;
    const sourceEvent = matchedEvent || sourceEvents[index] || null;
    if (!sourceEvent) return null;

    const fallbackActions = buildFallbackActions(sourceEvent);
    const actions = Array.isArray(entry?.actions) && entry.actions.length
      ? entry.actions.slice(0, 3).map((action, actionIndex) => normalizeAction(action, fallbackActions[actionIndex] || fallbackActions[0], sourceEvent))
      : fallbackActions;
    const resolvedEventId = sanitizeText(sourceEvent?.id);

    return {
      id: resolvedEventId,
      threadId: resolvedEventId,
      title: sanitizeText(entry?.title, sourceEvent?.summary || 'Tanpa judul'),
      actions,
    };
  })
  .filter(Boolean);

if (!normalizedAgendaActions.length) {
  for (const event of sourceEvents) {
    const eventId = sanitizeText(event?.id);
    normalizedAgendaActions.push({
      id: eventId,
      threadId: eventId,
      title: sanitizeText(event?.summary, 'Tanpa judul'),
      actions: buildFallbackActions(event),
    });
  }
}

return [
  {
    json: {
      calendar_briefing: {
        domain: 'calendar',
        status: parsed.status || 'partial',
        priority: parsed.priority || 'medium',
        agenda_actions: normalizedAgendaActions,
        source_metrics: {
          ...safeSourceMetrics,
          agenda_action_count: normalizedAgendaActions.length,
        }
      }
    }
  }
];

const raw = String($json.output || $json.text || '').trim();
const match = raw.match(/\{[\s\S]*\}/);
let parsed = {};

if (match) {
  try {
    parsed = JSON.parse(match[0]);
  } catch {
    parsed = {};
  }
}

return [
  {
    json: {
      jira_briefing: {
        domain: 'jira',
        status: parsed.status || 'partial',
        priority: parsed.priority || 'medium',
        source_metrics: parsed.source_metrics || {}
      }
    }
  }
];

const raw = String($json.output || $json.text || '').trim();
const match = raw.match(/\{[\s\S]*\}/);
let parsed = {};

if (match) {
  try {
    parsed = JSON.parse(match[0]);
  } catch {
    parsed = {};
  }
}

const sourcePayload = $('Aggregate Email Details').item.json || {};
const sourceEmails = Array.isArray(sourcePayload.emails) ? sourcePayload.emails.slice(0, 5) : [];
const safeSourceMetrics = parsed.source_metrics && typeof parsed.source_metrics === 'object'
  ? parsed.source_metrics
  : (sourcePayload.source_metrics || {});
const sanitizeText = (value, fallback = '') => {
  const normalized = String(value || '').trim();
  return normalized || fallback;
};
const looksAutomated = (email) => {
  const from = sanitizeText(email?.from).toLowerCase();
  const subject = sanitizeText(email?.subject).toLowerCase();
  const snippet = sanitizeText(email?.snippet).toLowerCase();
  const body = sanitizeText(email?.body).toLowerCase();
  const haystack = `${from} ${subject} ${snippet} ${body}`;

  const automatedSignals = [
    'no-reply',
    'noreply',
    'notification',
    'notifications',
    'digest',
    'newsletter',
    'unsubscribe',
    'calendar',
    'google',
    'jira',
    'atlassian',
    'github',
    'figma',
    'system alert',
    'billing alert',
    'app update',
    'do-not-reply',
  ];

  return automatedSignals.some((signal) => haystack.includes(signal));
};
const scoreEmail = (email) => {
  const from = sanitizeText(email?.from).toLowerCase();
  const subject = sanitizeText(email?.subject).toLowerCase();
  const snippet = sanitizeText(email?.snippet).toLowerCase();
  const body = sanitizeText(email?.body).toLowerCase();
  const haystack = `${subject} ${snippet} ${body}`;
  let score = 0;

  if (!looksAutomated(email)) score += 4;
  if (haystack.includes('please') || haystack.includes('could you') || haystack.includes('can you')) score += 2;
  if (haystack.includes('reply') || haystack.includes('respond') || haystack.includes('feedback')) score += 2;
  if (haystack.includes('meeting') || haystack.includes('proposal') || haystack.includes('confirm')) score += 1;
  if (from.includes('@gmail.com') || from.includes('@outlook.com') || from.includes('@yahoo.com')) score += 1;

  return score;
};
const emailLookup = new Map(sourceEmails.map((email) => [sanitizeText(email?.id), email]).filter(([id]) => id));
const bestFallbackEmail = sourceEmails
  .filter((email) => !looksAutomated(email))
  .sort((a, b) => scoreEmail(b) - scoreEmail(a))[0] || null;
const selectedEmailId = sanitizeText(parsed?.focus_email?.id);
const selectedThreadId = sanitizeText(parsed?.focus_email?.threadId);
const matchedFocusEmail = sourceEmails.find((email) => sanitizeText(email?.id) === selectedEmailId || sanitizeText(email?.threadId) === selectedThreadId) || null;
const focusEmail = matchedFocusEmail || bestFallbackEmail;
const buildEmailDetails = (email) => {
  if (!email || typeof email !== 'object') return 'Detail email belum tersedia.';
  return `Pengirim: ${sanitizeText(email?.from, '-')}` +
    `\nSubject: ${sanitizeText(email?.subject, '(Tanpa subjek)')}` +
    `\nSnippet: ${sanitizeText(email?.snippet, '-')}` +
    `\nBody ringkas: ${sanitizeText(email?.body || email?.snippet, '-')}`;
};
const buildEmailContext = (email) => ({
  briefing_domain: 'email',
  focus: 'priority_follow_up',
  email_ids: sanitizeText(email?.id) ? [sanitizeText(email?.id)] : [],
  thread_id: sanitizeText(email?.threadId),
  email_id: sanitizeText(email?.id),
  email_from: sanitizeText(email?.from),
  email_subject: sanitizeText(email?.subject, '(Tanpa subjek)'),
  email_snippet: sanitizeText(email?.snippet),
  email_body: sanitizeText(email?.body || email?.snippet),
});
const normalizedFocusEmail = focusEmail ? {
  id: sanitizeText(focusEmail.id),
  threadId: sanitizeText(focusEmail.threadId, sanitizeText(focusEmail.id)),
  reason: sanitizeText(parsed?.focus_email?.reason, 'Email ini paling layak ditindaklanjuti karena tampak berasal dari pengirim yang benar-benar mengharapkan respons.'),
  action: {
    label: 'Buatkan Draft',
    intent: 'draft_reply',
    target: 'supervisor',
    prompt: sanitizeText(parsed?.focus_email?.action?.prompt, 'Buatkan draft balasan profesional untuk email prioritas ini.') + `\n\nKonteks email lengkap:\n${buildEmailDetails(focusEmail)}`,
    context: {
      ...buildEmailContext(focusEmail),
      ...(parsed?.focus_email?.action?.context && typeof parsed.focus_email.action.context === 'object' ? parsed.focus_email.action.context : {}),
      ...buildEmailContext(focusEmail),
    },
  },
} : null;

return [
  {
    json: {
      email_briefing: {
        domain: 'email',
        status: parsed.status || 'partial',
        priority: parsed.priority || (normalizedFocusEmail ? 'high' : 'low'),
        focus_email: normalizedFocusEmail,
        source_metrics: {
          ...safeSourceMetrics,
          ignored_automated_candidates: sourceEmails.filter(looksAutomated).length,
          follow_up_candidate_found: Boolean(normalizedFocusEmail),
        }
      }
    }
  }
];

return [
  {
    json: {
      success: true,
      user_id: $('Prepare Request Data').item.json.user_id || '',
      generated_at: new Date().toISOString(),
      briefings: {
        jira: $json.jira_briefing || null,
        calendar: $json.calendar_briefing || null,
        email: $json.email_briefing || null
      }
    }
  }
];

const payload = $json || {};
const userId = String(payload.user_id || '').trim();
const generatedAt = payload.generated_at || new Date().toISOString();
const briefings = payload.briefings && typeof payload.briefings === 'object' ? payload.briefings : {};
const allowedPriorities = new Set(['high', 'medium', 'low']);
const allowedStatuses = new Set(['success', 'partial', 'failed']);
const rows = [];

for (const domain of ['jira', 'calendar', 'email']) {
  const briefing = briefings[domain];
  if (!briefing || !userId) continue;

  rows.push({
    user_id: userId,
    domain,
    priority: allowedPriorities.has(briefing.priority) ? briefing.priority : 'medium',
    headline: 'Briefing metadata only',
    summary_points: [],
    source_metrics: briefing.source_metrics && typeof briefing.source_metrics === 'object' ? briefing.source_metrics : {},
    generated_at: generatedAt,
    status: allowedStatuses.has(briefing.status) ? briefing.status : 'success',
    error_message: briefing.error_message ? String(briefing.error_message) : null,
  });
}

return [{
  json: {
    response_payload: payload,
    supabase_rows: rows,
  }
}];

const prepared = $('Prepare Supabase Upsert Rows').item.json || {};
return [{
  json: prepared.response_payload || {
    success: false,
    generated_at: new Date().toISOString(),
    briefings: {},
  }
}];
